/*
 * Fragment header for the roguelike overlay (see src/memmap.h `Fragment`).
 * Size fields are resolved by the RL linker script generated by
 * tools/rl/gen_rl_ld.py. Must be the first object in .fragmentRL.
 */
.include "macro.inc"

.set noat
.set noreorder

.section .text, "ax"

glabel fragmentRL_header
    j           rl_fragment_entry
     nop
    .ascii      "FRAGMENT"
    .word       0x00000020
    .word       fragmentRL_HDR_RELOC_OFFSET
    .word       fragmentRL_HDR_SIZE_IN_ROM
    .word       fragmentRL_HDR_SIZE_IN_RAM
